/// <summary>
/// CB233_TOReceiptDetails
/// The service class to run sys operartion job task.
/// </summary>
public class METInventTransferParmReceiveTaskService extends METSysOperationTaskService
{
    InventTransferParmTable parmTable;
    ParmId                  parmId;
    InventTransferId        transferId;

}

Method.Source:
/// <summary>
/// Runs task service class.
/// </summary>
/// <param name = "_contract">Contract of the task service class</param>
public void process(METSysOperationTaskDataContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Runs tasks of the task service class.
    /// </summary>
    /// <param name = "_readPast">Table read past setting</param>
    public void processTask(boolean _readPast)
    {
        parmTable.readPast(_readPast); // skip or don't skip locked records

        do
        {
            ttsbegin;
                      
            select firstOnly pessimisticlock parmTable
                where parmTable.JobStatus         == ParmJobStatus::Waiting
                && parmTable.METIsIntegration     == NoYes::Yes;

            if (parmTable)
            {
                this.execute();
            }

            ttscommit;
        }
        while (parmTable);
    }

/// <summary>
/// Executes the main process.
/// </summary>
private void execute()
{
    parmId = parmTable.ParmId;
    transferId = parmTable.TransferId;
    
    this.registerLines();
    //Post the receiving of the order.
    InventTransferMultiReceive::construct().runUpdate(parmTable);
    this.updateParmTableJobStatus(ParmJobStatus::Executed);
}

    /// <summary>
    /// Register the lines of the order.
    /// </summary>
    protected void registerLines()
    {
        METInventTransRegisterService registerService;
        InventTransferParmLine parmLine;

        while select parmLine
            where parmLine.ParmId == parmTable.ParmId
            && parmLine.TransferId == parmTable.TransferId
            && parmLine.QtyReceiveNow != 0
            && parmLine.PdsCWQtyReceiveNow != 0
        {
            registerService = METInventTransRegisterService::contruct(parmLine.InventTransId
                , parmLine.QtyReceiveNow
                , parmLine.PdsCWQtyReceiveNow);

            registerService.register();
        }
    }

    private void updateParmTableJobStatus(ParmJobStatus _jobStatus)
    {
        InventTransferParmTable parmTableUpdate;
        
        parmTableUpdate = InventTransferParmTable::find(parmId, transferId);

        if (parmTableUpdate)
        {
            ttsbegin;
            parmTableUpdate.selectForUpdate(true);
            parmTableUpdate.JobStatus = _jobStatus;
            parmTableUpdate.update();
            ttscommit;
        }
    }

/// <summary>
/// Updates <c>PurchParmTable</c> on error.
/// </summary>
protected void updateOnError()
{
    this.updateParmTableJobStatus(ParmJobStatus::ContainErrors);
}
